export function splitKey(key: string): string[] {
  const parts: string[] = [];
  let current = '';
  let inQuotes = false;
  let quoteChar = '';

  for (let i = 0; i < key.length; i++) {
    const char = key[i];

    if (inQuotes) {
      if (char === '\\' && i + 1 < key.length) {
        current += key[++i];
      } else if (char === quoteChar) {
        inQuotes = false;
      } else {
        current += char;
      }
    } else {
      if (char === '"' || char === "'") {
        inQuotes = true;
        quoteChar = char;
      } else if (char === '.') {
        parts.push(current);
        current = '';
      } else {
        current += char;
      }
    }
  }

  parts.push(current);
  return parts;
}

