+/* ── css/components/buttons.css ── */
+.btn {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  font-family: var(--font-display-condensed);
+  font-size: 1.15rem;
+  text-transform: uppercase;
+  letter-spacing: 0.08em;
+  padding: 0.85rem 2rem;
+  border-radius: 2px;
+  transition: transform var(--transition-fast), box-shadow var(--transition-fast), background-color var(--transition-fast), border-color var(--transition-fast);
+  cursor: pointer;
+  position: relative;
+}
+
+/* ── Milim Action (Primary) ── */
+.btn-primary {
+  background-color: var(--milim-pink);
+  color: var(--bg);
+  border: none;
+  box-shadow: 2px 2px 0px var(--rimuru-blue);
+}
+
+.btn-primary:hover {
+  transform: translate(-2px, -2px);
+  box-shadow: 6px 6px 0px var(--rimuru-blue);
+}
+
+.btn-primary:active {
+  transform: translate(0px, 0px);
+  box-shadow: 2px 2px 0px var(--rimuru-blue);
+}
+
+/* ── Rimuru Outline (Secondary) ── */
+.btn-secondary {
+  background-color: transparent;
+  color: var(--text);
+  border: 1px solid var(--border);
+}
+
+.btn-secondary:hover {
+  border-color: var(--rimuru-blue);
+  background-color: var(--rimuru-blue-bg);
+  color: var(--rimuru-blue);
+}
+
+.btn-secondary:active {
+  background-color: rgba(56, 189, 248, 0.15);
+}
+
+/* Button Group utilities */
+.btn-group {
+  display: flex;
+  gap: 1rem;
+}
+
+@media (max-width: 640px) {
