+/* ── css/components/hero.css ── */
+.hero-section {
+  display: flex;
+  flex-direction: column;
+  justify-content: center;
+  min-height: calc(85vh - 64px);
+  padding: 4rem 0;
+  position: relative;
+  overflow: hidden;
+}
+
+/* ── Hero Grid Accents ── */
+.hero-grid-guide {
+  position: absolute;
+  top: 0;
+  left: 50%;
+  width: 1px;
+  height: 100%;
+  background-color: var(--border-muted);
+  z-index: -1;
+}
+
+/* ── Kicker & Mascot Banner ── */
+.hero-kicker-wrapper {
+  margin-bottom: 1.5rem;
+}
+.hero-mascot-pill {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.5rem;
+  background-color: var(--milim-pink-bg);
+  border: 1px solid var(--milim-pink-border);
+  padding: 0.4rem 0.8rem;
+  border-radius: 2px;
+  font-family: var(--font-mono);
+  font-size: 0.72rem;
+  color: var(--milim-pink);
+  text-transform: uppercase;
+  letter-spacing: 0.05em;
+  transform: rotate(-1deg);
+}
+
+.hero-mascot-pill span.spark {
+  display: inline-block;
+  animation: spark-shimmer 1.5s infinite;
+}
+
+/* ── Hero Main Title (Syne) ── */
+.hero-title {
+  font-family: var(--font-display-wide);
+  font-weight: 800;
+  font-size: clamp(2.8rem, 8vw, 5.5rem);
+  line-height: 0.95;
+  letter-spacing: -0.03em;
+  text-transform: uppercase;
+  color: var(--text);
+  margin-bottom: 2rem;
+}
+
+.hero-title span.strike-pink {
+  color: var(--milim-pink);
+  position: relative;
+}
+.hero-title span.strike-pink::after {
+  content: '';
+  position: absolute;
+  bottom: 5px;
+  left: 0;
