--- /dev/null
+++ b/css/layout.css
@@ -0,0 +1,102 @@
+/* ── css/layout.css ── */
+.lab-canvas {
+  width: 100%;
+  max-width: 1200px;
+  margin: 0 auto;
+  padding: 0 1.5rem;
+  position: relative;
+}
+
+/* ── Laboratory Background Grid Pattern ── */
+.grid-bg {
+  position: fixed;
+  top: 0;
+  left: 0;
+  width: 100vw;
+  height: 100vh;
+  background-image: 
+    linear-gradient(to right, var(--border-muted) 1px, transparent 1px),
+    linear-gradient(to bottom, var(--border-muted) 1px, transparent 1px);
+  background-size: 40px 40px;
+  z-index: -10;
+  pointer-events: none;
+  opacity: 0.7;
+}
+
+/* ── Horizontal Grid Divider lines ── */
+.grid-divider-h {
+  width: 100%;
+  height: 1px;
+  background-color: var(--border);
+  position: relative;
+}
+.grid-divider-h::after {
+  content: '';
+  position: absolute;
+  top: 0;
+  left: 10%;
+  width: 4px;
+  height: 4px;
+  background: var(--milim-pink);
+  transform: translateY(-1.5px);
+}
+
+/* ── Vertical Grid Border guides (only visible on desktop) ── */
+@media (min-width: 1200px) {
+  .lab-canvas::before,
+  .lab-canvas::after {
+    content: '';
+    position: absolute;
+    top: 0;
+    width: 1px;
+    height: 100%;
+    background-color: var(--border);
+    z-index: -1;
+  }
+  .lab-canvas::before {
+    left: 0;
+  }
+  .lab-canvas::after {
+    right: 0;
+  }
+}
+
+/* ── Section Container ── */
+section {
+  padding: 5rem 0;
+  border-bottom: 1px solid var(--border-muted);
+}
+@media (max-width: 768px) {
+  section {
+    padding: 3.5rem 0;
+  }
+}
+
+/* ── Flex & Grid Utilities ── */
+.flex-row {
+  display: flex;
+  align-items: center;
+  gap: 1rem;
+}
+.grid-cols-2 {
+  display: grid;
+  grid-template-columns: repeat(2, 1fr);
+  gap: 1.5rem;
+}
+.grid-cols-3 {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 1.5rem;
+}
+
+@media (max-width: 992px) {
+  .grid-cols-3 {
+    grid-template-columns: repeat(2, 1fr);
+  }
+}
+@media (max-width: 640px) {
+  .grid-cols-2, .grid-cols-3 {
+    grid-template-columns: 1fr;
+    gap: 1rem;
+  }
+}
diff --git a/css/style.css b/css/style.css
new file mode 100644
