      }
    }
```

* **Tracking**: Initializes `visitedKeys = new Set<string>([key])` for each configuration entry.
* **Cycle Traversal**: Follows string value references (both direct key references like `'server.host'` and template interpolations like `'${server.host}'`).
* **Detection & Error**: If a referenced key already exists in `visitedKeys`, it throws `new ConfigError('Circular reference detected')`.
* **Termination**: If the value does not reference an existing key in `raw` or is non-string, it terminates immediately and continues with path parsing.

export class ConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ConfigError';
  }
}

export function splitKey(key: string): string[] {
  const parts: string[] = [];
  let current = '';
  let inQuotes = false;
  let quoteChar = '';

  for (let i = 0; i < key.length; i++) {
    const char = key[i];

    if (inQuotes) {
      if (char === '\\' && i + 1 < key.length) {
        current += key[++i];
      } else if (char === quoteChar) {
        inQuotes = false;
      } else {
        current += char;
      }
    } else {
      if (char === '"' || char === "'") {
        inQuotes = true;
        quoteChar = char;
      } else if (char === '.' || char === '[') {
        if (current.length > 0) {
          parts.push(current);
          current = '';
        }
      } else if (char === ']') {
        if (current.length > 0) {
          parts.push(current);
          current = '';
        }
      } else {
        current += char;
      }
    }
  }

  if (current.length > 0 || parts.length === 0) {
    parts.push(current);
  }
  return parts;
}

export function parseConfig(raw: Record<string, any>): Record<string, any> {
  const result: Record<string, any> = {};

  for (const [key, value] of Object.entries(raw)) {
    const visitedKeys = new Set<string>([key]);
    let currentVal = value;

    while (typeof currentVal === 'string') {
      const targetKey = currentVal in raw
        ? currentVal
        : currentVal.match(/^\$\{([^}]+)\}$/)?.[1];

      if (targetKey && targetKey in raw) {
        if (visitedKeys.has(targetKey)) {
          throw new ConfigError('Circular reference detected');
        }
        visitedKeys.add(targetKey);
        currentVal = raw[targetKey];
      } else {
        break;
      }
    }

    const parts = splitKey(key);
    let current: any = result;

    for (let i = 0; i < parts.length - 1; i++) {
      const part = parts[i];
      const nextPart = parts[i + 1];
      const isNextIndex = /^\d+$/.test(nextPart);

      if (!(part in current)) {
        current[part] = isNextIndex ? [] : {};
      }
      current = current[part];
    }

    const lastPart = parts[parts.length - 1];
    current[lastPart] = value;
  }

  return result;
}

