  constructor(message: string) {
    super(message);
    this.name = 'ConfigError';
  }
}

const NUMERIC_INDEX_REGEX = /^\d+$/;
const INTERPOLATION_REGEX = /^\$\{([^}]+)\}$/;

/**
 * Splits a configuration key path into its constituent segment tokens.
 * Supports dot notation, quoted keys containing literal dots or brackets, and array indexing brackets.
 *
 * @param key - The raw configuration key path string to tokenize.
 * @returns An array of string path segments.
 * @throws {ConfigError} When encountering malformed or unclosed quoted path segments.
 */
export function splitKey(key: string): string[] {
  const parts: string[] = [];
  let current = '';
  let inQuotes = false;
  let quoteChar = '';

  for (let i = 0; i < key.length; i++) {
    const char = key[i];

    if (inQuotes) {
      if (char === '\\' && i + 1 < key.length) {
        current += key[++i];
      } else if (char === quoteChar) {
        inQuotes = false;
      } else {
        current += char;
      }
    } else {
      if (char === '"' || char === "'") {
        inQuotes = true;
        quoteChar = char;
      } else if (char === '.' || char === '[' || char === ']') {
        if (current.length > 0) {
          parts.push(current);
          current = '';
        }
      } else {
        current += char;
      }
    }
  }

  if (current.length > 0 || parts.length === 0) {
    parts.push(current);
  }
  return parts;
}

/**
 * Validates that a configuration key and its value references do not form a cycle.
 *
 * @param key - Initial key path to check.
 * @param value - Initial value to trace.
 * @param raw - Complete dictionary of configuration entries.
 * @throws {ConfigError} If a circular reference chain is detected.
 */
function assertNoCircularReference(key: string, value: any, raw: Record<string, any>): void {
  const visitedKeys = new Set<string>([key]);
  let currentVal = value;

  while (typeof currentVal === 'string') {
    const targetKey = currentVal in raw
      ? currentVal
      : currentVal.match(INTERPOLATION_REGEX)?.[1];

    if (targetKey && targetKey in raw) {
      if (visitedKeys.has(targetKey)) {
        throw new ConfigError('Circular reference detected');
      }
      visitedKeys.add(targetKey);
      currentVal = raw[targetKey];
    } else {
      break;
    }
  }
}

/**
 * Parses a flat configuration dictionary into a deeply nested object hierarchy,
 * expanding dot-delimited and bracket-indexed path keys while detecting circular references.
 *
 * @param raw - A flat key-value record containing configuration paths and their values.
 * @returns A structured configuration object containing nested objects and arrays.
 * @throws {ConfigError} If a circular reference is detected among key value references.
 */
export function parseConfig(raw: Record<string, any>): Record<string, any> {
  const result: Record<string, any> = {};

  for (const [key, value] of Object.entries(raw)) {
    assertNoCircularReference(key, value, raw);

    const parts = splitKey(key);
    let current: any = result;

    for (let i = 0; i < parts.length - 1; i++) {
      const part = parts[i];
      const nextPart = parts[i + 1];
      const isNextIndex = NUMERIC_INDEX_REGEX.test(nextPart);

      if (!(part in current)) {
        current[part] = isNextIndex ? [] : {};
      }
      current = current[part];
    }

    const lastPart = parts[parts.length - 1];
    current[lastPart] = value;
  }

  return result;
}

